from __future__ import annotations

import base64
import gzip
import hashlib
import json
import sqlite3
from pathlib import Path


BASE_DIR = Path(__file__).resolve().parent
DATABASE_PATH = BASE_DIR / "database" / "footwin_sports.db"

MIGRATION_ID = "0009_seed_fra1_ita1_ger1_frozen"
DESCRIPTION = (
    "Seed idempotente dos calendários FRA1/ITA1/GER1 e dos "
    "PRE_MATCH congelados já publicados em 2026/27"
)

EXPECTED_MATCHES = 992
EXPECTED_PREDICTIONS = 695
EXPECTED_PAYLOAD_SHA256 = "6a55cf4a292e467f4442f9705f4ac543e6d5cb45a4ea941e630bd1744076eb06"

PAYLOAD_B64 = """"""


def load_payload() -> dict:
    compressed = base64.b64decode(
        PAYLOAD_B64.encode("ascii")
    )
    raw = gzip.decompress(compressed)

    actual_hash = hashlib.sha256(raw).hexdigest()

    if actual_hash != EXPECTED_PAYLOAD_SHA256:
        raise RuntimeError(
            "Payload 0009 corrompido: hash inesperado."
        )

    payload = json.loads(
        raw.decode("utf-8")
    )

    if len(payload["matches"]) != EXPECTED_MATCHES:
        raise RuntimeError(
            "Quantidade de matches no payload 0009 inesperada."
        )

    if (
        len(payload["predictions"])
        != EXPECTED_PREDICTIONS
    ):
        raise RuntimeError(
            "Quantidade de PRE_MATCH no payload 0009 inesperada."
        )

    return payload


def insert_missing_row(
    connection: sqlite3.Connection,
    table: str,
    pk_name: str,
    row: dict,
) -> bool:
    existing = connection.execute(
        f"SELECT 1 FROM {table} WHERE {pk_name} = ?",
        (row[pk_name],),
    ).fetchone()

    if existing is not None:
        return False

    columns = list(row)
    placeholders = ", ".join(
        "?" for _ in columns
    )
    column_sql = ", ".join(columns)

    connection.execute(
        f"""
        INSERT INTO {table} (
            {column_sql}
        )
        VALUES ({placeholders})
        """,
        tuple(row[column] for column in columns),
    )

    return True


def main() -> int:
    payload = load_payload()

    connection = sqlite3.connect(
        DATABASE_PATH
    )
    connection.row_factory = sqlite3.Row

    inserted_matches = 0
    inserted_predictions = 0

    try:
        connection.execute(
            "PRAGMA foreign_keys = ON"
        )
        connection.execute(
            "BEGIN IMMEDIATE"
        )

        for row in payload["matches"]:
            if insert_missing_row(
                connection=connection,
                table="matches",
                pk_name="match_id",
                row=row,
            ):
                inserted_matches += 1

        for row in payload["predictions"]:
            if insert_missing_row(
                connection=connection,
                table="match_predictions",
                pk_name="prediction_id",
                row=row,
            ):
                inserted_predictions += 1

        counts = {}

        for league_id in (
            "FRA1",
            "ITA1",
            "GER1",
        ):
            matches = connection.execute(
                """
                SELECT COUNT(*)
                FROM matches
                WHERE league_id = ?
                  AND season_label = '2026/27'
                """,
                (league_id,),
            ).fetchone()[0]

            pre_match = connection.execute(
                """
                SELECT COUNT(*)
                FROM match_predictions AS p
                JOIN matches AS m
                  ON m.match_id = p.match_id
                WHERE m.league_id = ?
                  AND m.season_label = '2026/27'
                  AND p.prediction_stage = 'PRE_MATCH'
                """,
                (league_id,),
            ).fetchone()[0]

            counts[league_id] = {
                "matches": int(matches),
                "pre_match": int(pre_match),
            }

        expected = {
            "FRA1": {
                "matches": 306,
                "pre_match": 306,
            },
            "ITA1": {
                "matches": 380,
                "pre_match": 380,
            },
            "GER1": {
                "matches": 306,
                "pre_match": 9,
            },
        }

        if counts != expected:
            raise RuntimeError(
                "Validação 0009 falhou: "
                f"counts={counts}"
            )

        fk_errors = list(
            connection.execute(
                "PRAGMA foreign_key_check"
            )
        )

        if fk_errors:
            raise RuntimeError(
                "Foreign keys inválidas após 0009: "
                f"{fk_errors[:10]}"
            )

        connection.commit()

    except Exception:
        connection.rollback()
        raise

    finally:
        connection.close()

    print(
        "0009 OK | "
        f"inserted_matches={inserted_matches} | "
        f"inserted_predictions={inserted_predictions}"
    )

    for league_id, values in counts.items():
        print(
            league_id,
            "| matches =",
            values["matches"],
            "| PRE_MATCH =",
            values["pre_match"],
        )

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
